CREATE DATABASE IF NOT EXISTS laksela_store CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE laksela_store;
CREATE TABLE IF NOT EXISTS categories (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, slug VARCHAR(140) NOT NULL UNIQUE, count_label INT DEFAULT 0, icon VARCHAR(10) DEFAULT '⌂');
CREATE TABLE IF NOT EXISTS brands (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL UNIQUE, slug VARCHAR(120) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS products (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(220) NOT NULL, slug VARCHAR(240) NOT NULL UNIQUE, sku VARCHAR(80), category_id INT, brand_id INT, price DECIMAL(12,2) NOT NULL, old_price DECIMAL(12,2), stock INT DEFAULT 0, image_url TEXT, short_desc TEXT, description TEXT, sold_count INT DEFAULT 0, featured TINYINT DEFAULT 0, best_selling TINYINT DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(category_id) REFERENCES categories(id), FOREIGN KEY(brand_id) REFERENCES brands(id), INDEX(price), INDEX(category_id));
CREATE TABLE IF NOT EXISTS users (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(140), email VARCHAR(190) UNIQUE, password_hash VARCHAR(255), phone VARCHAR(32), address TEXT, role ENUM('customer','admin') DEFAULT 'customer', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS orders (id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NULL, order_number VARCHAR(40) UNIQUE, name VARCHAR(140), email VARCHAR(190), phone VARCHAR(32), address TEXT, subtotal DECIMAL(12,2), discount DECIMAL(12,2) DEFAULT 0, total DECIMAL(12,2), payment_method ENUM('cod','payhere','koko','bank') DEFAULT 'cod', payment_status ENUM('unpaid','pending','paid','failed','refunded') DEFAULT 'unpaid', payment_reference VARCHAR(160) NULL, status ENUM('pending','processing','completed','cancelled') DEFAULT 'pending', note TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS order_items (id INT AUTO_INCREMENT PRIMARY KEY, order_id INT NOT NULL, product_id INT NULL, product_name VARCHAR(220), price DECIMAL(12,2), quantity INT, FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE, FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS coupons (id INT AUTO_INCREMENT PRIMARY KEY, code VARCHAR(40) UNIQUE, discount_percent DECIMAL(5,2), active TINYINT DEFAULT 1);
